fn ease_in(n16: i32) -> i32 {
    n16 * n16 / 16
}

fn ease_out(n16: i32) -> i32 {
    16 - (16 - n16) * (16 - n16) / 16
}

fn ease_io(n16: i32) -> i32 {
    if n16 < 8 {
        ease_in(n16 * 2) / 2
    } else {
        8 + ease_out((n16 - 8) * 2) / 2
    }
}

fn tween(a: i32, b: i32, n16: i32, mode: i32) -> i32 {
    let mut e: i32 = n16;
    if mode == 1 { e = ease_in(n16); }
    if mode == 2 { e = ease_out(n16); }
    if mode == 3 { e = ease_io(n16); }
    a + (b - a) * e / 16
}

fn dims() -> i32 {
    (256 << 16) | 152
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB EASE", 0xffffff, 2);
    host::display::draw_string(8, 30, "IN OUT IO TWEEN", 0x00ff66, 1);
    let mut n: i32 = t % 64;
    if n > 32 { n = 64 - n; }
    let n16: i32 = n / 2;
    host::display::fill_rect(tween(8, 224, n16, 0), 56, 24, 16, 0x808080);
    host::display::fill_rect(tween(8, 224, n16, 1), 78, 24, 16, 0xff8040);
    host::display::fill_rect(tween(8, 224, n16, 2), 100, 24, 16, 0x40c0ff);
    host::display::fill_rect(tween(8, 224, n16, 3), 122, 24, 16, 0x40ff80);
    host::display::present();
}
